-- CC_0018_fl_legislature_photo_fields.sql
-- Point Florida's 155 sitting state legislators at the headshots we now host, and put the
-- real provenance page in photo_origin_url.
--
-- WHY THIS IS NEEDED AFTER THE IMPORT ALREADY RAN. The import created a politician_images
-- row for all 155 and mirrored the bytes into our bucket. That is not enough to change what
-- a voter sees. The address-search path builds its photo from
--     COALESCE(p.photo_custom_url, p.photo_origin_url, '')
-- (backend/src/lib/districtQueries.ts, DISTRICT_SELECT_FIELDS) and NEVER READS
-- politician_images at all. essentialsBodiesService.ts does read it, but only third, after
-- photo_origin_url. So with photo_custom_url unset these 155 kept rendering from the
-- chamber hotlink -- the exact thing the wave set out to remove.
--
-- THE TWO FIELDS ARE NOT INTERCHANGEABLE AND THE ORDER OF THIS FIX MATTERS.
-- photo_custom_url is what RENDERS. photo_origin_url is PROVENANCE. Rewriting
-- photo_origin_url to a source page WITHOUT setting photo_custom_url first would hand an
-- HTML page to an <img src> and break all 155 on the flagship surface.
--
-- Both updates are guarded on the value they expect to replace, so a re-run is a no-op and
-- a row somebody has since edited by hand is left alone.
--
-- Sources: www.flhouse.gov and www.flsenate.gov member rosters, read 2026-08-30.
-- Licence recorded as public_domain, matching the 4 Florida STATE_EXEC rows.

BEGIN;

CREATE TEMP TABLE _fl_leg_photos (pid uuid, cdn_url text, source_page text, old_hotlink text)
  ON COMMIT DROP;

;

-- 1. What renders: our mirrored copy. Only fill a field that is empty.
UPDATE essentials.politicians p
   SET photo_custom_url = f.cdn_url
  FROM _fl_leg_photos f
 WHERE p.id = f.pid
   AND btrim(COALESCE(p.photo_custom_url, '')) = '';

-- 2. What it came from: the member's own page, replacing the raw image hotlink.
UPDATE essentials.politicians p
   SET photo_origin_url = f.source_page
  FROM _fl_leg_photos f
 WHERE p.id = f.pid
   AND p.photo_origin_url = f.old_hotlink;

DO $$
DECLARE
  n_total         int;
  n_no_render     int;
  n_still_hotlink int;
  n_no_image_row  int;
BEGIN
  SELECT count(*) INTO n_total FROM _fl_leg_photos;
  IF n_total <> 155 THEN
    RAISE EXCEPTION 'expected 155 Florida legislators, got %', n_total;
  END IF;

  -- Every one must now RENDER from our bucket.
  SELECT count(*) INTO n_no_render
    FROM _fl_leg_photos f JOIN essentials.politicians p ON p.id = f.pid
   WHERE COALESCE(NULLIF(btrim(p.photo_custom_url), ''), p.photo_origin_url, '')
         NOT LIKE '%storage.supabase.co%';
  IF n_no_render <> 0 THEN
    RAISE EXCEPTION '% legislator(s) would still render from a third-party host', n_no_render;
  END IF;

  -- And none may still carry a raw image URL in the provenance field.
  SELECT count(*) INTO n_still_hotlink
    FROM _fl_leg_photos f JOIN essentials.politicians p ON p.id = f.pid
   WHERE p.photo_origin_url ~* '\.(jpg|jpeg|png|webp)(\?|$)';
  IF n_still_hotlink <> 0 THEN
    RAISE EXCEPTION '% row(s) still hold a raw image URL in photo_origin_url', n_still_hotlink;
  END IF;

  SELECT count(*) INTO n_no_image_row
    FROM _fl_leg_photos f
   WHERE NOT EXISTS (SELECT 1 FROM essentials.politician_images i WHERE i.politician_id = f.pid);
  IF n_no_image_row <> 0 THEN
    RAISE EXCEPTION '% legislator(s) have no politician_images row', n_no_image_row;
  END IF;

  RAISE NOTICE 'OK: 155 Florida legislators render from our bucket, provenance is a source page';
END $$;

COMMIT;
